import { openContractCall, verifyBtcStacksPair } from '@stacks/connect';

const redeemWithBtcVerification = async () => {
  const isVerified = await verifyBtcStacksPair(
    userSession,
    btcAddress,
    stacksAddress
  );

  if (isVerified) {
    await openContractCall(redemptionOptions);
  }
};

const verifyDualOwnership = async (btcAddress, stacksAddress) => {
  const proof = await xverse.getOwnershipProof(btcAddress, stacksAddress);
  return verifySignature(proof);
};

